parameters.jsCode:
// Exnoria - prd.contact.educate
// Feature education for contacts using workarounds (PRD_CAP_01)

const webhook = $("Webhook").first().json.body;
const contact = $input.first().json;

const { contact_id, signal_id } = webhook;
const feature_area = webhook.payload?.feature_area ?? webhook.feature_area ?? 'your workflow';

const firstname = contact.properties?.firstname?.value ?? 'there';
const email     = contact.properties?.email?.value     ?? '';
const phone     = contact.properties?.phone?.value     ?? '';

const cleanPhone = phone.replace(/[^\d]/g, '');

const message = [
  'Hi ' + firstname + ',',
  '',
  'Did you know there\'s a built-in way to handle ' + feature_area + '?',
  '',
  'We noticed you might be using a workaround — here\'s a quick guide to the native feature that can save you time: [Feature Guide Link]',
  '',
  'Let us know if you have any questions!',
  '',
  '-- Exnoria Product Team'
].join('\n');

const whatsapp_payload = cleanPhone ? {
  messaging_product: 'whatsapp',
  to: cleanPhone,
  type: 'text',
  text: { body: message }
} : null;

const educatedAt = new Date(new Date().setUTCHours(0,0,0,0)).getTime();

return [{
  json: {
    contact_id,
    signal_id,
    feature_area,
    email,
    firstname,
    phone: cleanPhone,
    whatsapp_payload,
    csm_task_subject: '[Exnoria PRD] Check in on feature adoption for ' + contact_id,
    csm_task_due_days: 7,
    educated_at: educatedAt
  }
}];

// Simulate -- HubSpot task creation for CSM follow-up in 7 days
// Replace with real HubSpot task API when ready

const data = $("Code -- educate logic").first().json;

return [{
  json: {
    ...data,
    task_created: true,
    task_id: 'task_sim_' + Date.now(),
    simulated: true
  }
}];

